exercise.solution:
// JavaScript track — same Prisma schema DSL; Zod validates inputs at the JS boundary.
model LabL10Publisher {
  id        Int              @id @default(autoincrement())
  name      String
  magazines LabL10Magazine[]
  @@map("lab_l10_publishers")
}

model LabL10Magazine {
  id          Int             @id @default(autoincrement())
  title       String
  publisherId Int             @map("publisher_id")
  publisher   LabL10Publisher @relation(fields: [publisherId], references: [id])
  @@map("lab_l10_magazines")
}

